    constructor() {
      super();

      this.buffers = []; // { buffer: Int16Array; markIndex: number; }[]
      this.activeBuffer = null; // { buffer: Int16Array; markIndex: number; } | null
      this.cursor = 0;
      this.isPlaying = false;

      this.port.onmessage = ({ data }) => {
        if (data.type === 'chunk') {
          this.buffers.push({
            buffer: new Int16Array(data.chunk.buffer),
            markIndex: data.chunk.markIndex
          });
        }
        if (data.type === 'interrupt') {
          this.buffers = [];
          this.activeBuffer = null;
          if (this.isPlaying) {
            this.isPlaying = false;
            this.port.postMessage({ type: 'finished' });
          }
        }
      };
    }

