  class Linear16Processor extends AudioWorkletProcessor {
    constructor() {
      super();

      // Buffer accumulation to match the specified chunk size
      this.accumulatedSamples = [];
      this.sampleCounter = 0;
      this.chunkSize = 16000; // 1 second of audio at 16kHz

      this.port.onmessage = ({ data }) => {
        if (data.type === 'setChunkSize') {
          this.chunkSize = data.chunkSize;
        }
      };
    }

    process(inputs) {
      const input = inputs[0][0]; // Get the first channel of the first input

      if (!input || input.length === 0) {
        return true;
      }

      // Convert Float32Array to Int16Array
      const int16Data = new Int16Array(input.length);
      for (let i = 0; i < input.length; i++) {
        let sample = input[i];
        sample = Math.max(-1, Math.min(1, sample));
        sample = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
        int16Data[i] = Math.floor(sample);
      }

      // Add samples to accumulated buffer
      this.accumulatedSamples.push(...Array.from(int16Data));
      this.sampleCounter += input.length;

      // If we've accumulated enough samples, send them to the main thread
      if (this.sampleCounter >= this.chunkSize) {
        const samplesChunk = new Int16Array(this.accumulatedSamples.slice(0, this.chunkSize));

        // Send the buffer to the main thread
        this.port.postMessage({
          type: 'data',
          buffer: samplesChunk.buffer
        }, [samplesChunk.buffer]);

        // Remove sent samples and update counter
        this.accumulatedSamples = this.accumulatedSamples.slice(this.chunkSize);
        this.sampleCounter -= this.chunkSize;
      }

      return true; // Keep the processor running
    }
  }

  registerProcessor('linear16-processor', Linear16Processor);
